"""Scan the MULTIBOOT partition and write multiboot/menu.cfg plus add-ons."""
from __future__ import annotations

import hashlib
import os
import shutil
import subprocess
import tempfile
import textwrap
from pathlib import Path

from isolator.config import MenuConfig
from isolator.groups import Entries, Group, entry_ids, group, matches
from isolator.iso9660 import Iso
from isolator.profiles import SAFE_PATH, Result, detect

HEADER = """\
# menu.cfg - GENERATED by gen-menu.py, do not edit by hand.
# Manual entries: multiboot/local.cfg (included at the end).
# Variables provided by grub.cfg: $isopart (exFAT partition), $isolabel.
"""

FOOTER = """
# ===== Manual entries =========================================================
if [ -f ($isopart)/multiboot/local.cfg ]; then
    source ($isopart)/multiboot/local.cfg
fi
"""

ADDONS = "multiboot/addons"


def addon_name(rel: str) -> str:
    """One add-on per ISO path: the hash keeps "/a_b.iso" and "/a/b.iso"
    apart, the stem keeps the directory readable. SAFE_PATH holds for `rel`."""
    digest = hashlib.sha256(rel.encode()).hexdigest()[:12]
    return f"{Path(rel).stem}-{digest}.img"


def entry(rel: str, r: Result) -> str:
    title = r.title.replace('"', "").replace("$", "").replace("\\", "")
    title = " ".join(title.split())
    addon = f"    set addon=($isopart)/{ADDONS}/{addon_name(rel)}\n" if r.addon is not None else ""
    # `set iso` twice: once for the [ -f ] test, once inside the entry,
    # since GRUB runs the entry body later, after the loop has moved on.
    return (f"\nset iso={rel}\n"
            f"if [ -f ($isopart)$iso ]; then\n"
            f'menuentry "{title}" --class {r.css_class} --id {rel} {{\n'
            f"    set iso={rel}\n"
            f"{addon}"
            f"    loopback loop ($isopart)$iso\n"
            f"{r.body}"
            f"}}\n"
            f"fi\n")


def submenu(g: Group) -> str:
    body = textwrap.indent("".join(entry(rel, r) for rel, r in g.entries), "    ")
    return f'\nsubmenu "{g.title}" --class submenu --id {g.id} {{{body}}}\n'


def arrange(kept: Entries, cfg: MenuConfig) -> tuple[Entries, list[str]]:
    """Apply `hidden` then `order`; return the shown entries and hidden paths."""
    hidden = [rel for rel, _ in kept if any(matches(rel, p) for p in cfg.hidden)]
    rest = [(rel, r) for rel, r in kept if rel not in hidden]
    placed: list[str] = []
    for pattern in cfg.order:
        placed += [rel for rel, _ in rest if matches(rel, pattern) and rel not in placed]
    rank = {rel: i for i, rel in enumerate(placed)}
    # sorted() is stable: unplaced entries keep their title order.
    return sorted(rest, key=lambda e: rank.get(e[0], len(rank))), hidden


def resolve_default(cfg: MenuConfig, ids: set[str]) -> str | None:
    """The real path of the default entry: exFAT ignores case, GRUB ids do not."""
    if cfg.default is None:
        return None
    return next((i for i in sorted(ids) if i.lower() == cfg.default.lower()), None)


def settings(cfg: MenuConfig, ids: dict[str, str]) -> str:
    """GRUB variables; they override grub.cfg, which sources this menu.
    `ids` maps each ISO path to its GRUB id (see groups.entry_ids)."""
    lines = ""
    if cfg.timeout is not None:
        lines += f"set timeout={cfg.timeout}\n"
    default = resolve_default(cfg, set(ids))
    if default:
        lines += f'set default="{ids[default]}"\n'
    return lines


def render(kept: Entries, cfg: MenuConfig = MenuConfig()) -> str:
    top, groups = group(kept, cfg)
    return (HEADER + settings(cfg, entry_ids(top, groups))
            + "".join(entry(rel, r) for rel, r in top)
            + "".join(submenu(g) for g in groups) + FOOTER)


def _inspect(path: Path, rel: str, options: dict) -> Result:
    try:
        with Iso(path) as iso:
            if not iso.has("efi/boot/bootx64.efi"):
                return Result(refusal="no x86_64 UEFI loader (arm64 ISO?)")
            return detect(iso, rel, **options) or Result(refusal="unknown ISO type")
    except (OSError, ValueError, IndexError) as err:
        return Result(refusal=f"unreadable ({err})")


def analyse(root: Path, **options) -> tuple[list[tuple[str, Result]], list[tuple[str, str]]]:
    kept, skipped = [], []
    for path in sorted(root.rglob("*.iso", case_sensitive=False), key=lambda p: str(p).lower()):
        rel = "/" + path.relative_to(root).as_posix()
        if not SAFE_PATH.match(rel):
            skipped.append((rel, "forbidden characters in path (spaces, accents, $...)"))
            continue
        r = _inspect(path, rel, options)
        if r.refusal:
            skipped.append((rel, r.refusal))
        else:
            kept.append((rel, r))
    kept.sort(key=lambda x: x[1].title.lower())
    return kept, skipped


def check_syntax(menu: str) -> str:
    """grub-script-check output; empty when the menu is valid."""
    with tempfile.NamedTemporaryFile("w", suffix=".cfg") as tmp:
        tmp.write(menu)
        tmp.flush()
        res = subprocess.run(["grub-script-check", tmp.name], capture_output=True, text=True)
    return "" if res.returncode == 0 else (res.stdout + res.stderr or "invalid menu")


def write(root: Path, kept: Entries, cfg: MenuConfig = MenuConfig()) -> Path:
    addons = root / ADDONS
    for rel, r in kept:
        if r.addon is not None:
            addons.mkdir(exist_ok=True)
            (addons / addon_name(rel)).write_bytes(r.addon)
    target = root / "multiboot" / "menu.cfg"
    if target.exists():
        shutil.copy2(target, target.with_suffix(".cfg.bak"))
    # Write then rename: a crash or unplugged disk never leaves GRUB a truncated menu.
    tmp = target.with_suffix(".cfg.new")
    tmp.write_text(render(kept, cfg))
    os.replace(tmp, target)
    return target
